async function load(){ready=false;$('#retry').hidden=true;$('#curtain').hidden=false;$('#curtain-title').textContent='Opening the portal…';try{await Promise.all(Object.entries(assets).map(([n,f])=>loadImage(n,f)));buildFloor();ready=true;$('#curtain').hidden=true;drawInventoryIcon();resize();showHelp(true);notifyParent('entia-demo-ready');schedule();}catch(e){$('#curtain-title').textContent='The portal could not open';$('#curtain-text').textContent='An artwork file did not load. Please try again.';$('#retry').hidden=false;notifyParent('entia-demo-error');}}
function buildFloor(){const c=floor.getContext('2d');c.imageSmoothingEnabled=false;for(let y=0;y<M.HEIGHT;y+=M.TILE)for(let x=0;x<M.WIDTH;x+=M.TILE)c.drawImage(images.grass,x,y,M.TILE,M.TILE);c.save();c.beginPath();c.rect(128,384,864,96);c.rect(576,320,96,480);c.rect(128,480,96,224);c.clip();for(let y=0;y<M.HEIGHT;y+=M.TILE)for(let x=0;x<M.WIDTH;x+=M.TILE)c.drawImage(images.path,x,y,M.TILE,M.TILE);c.restore();for(let y=352;y<512;y+=M.TILE)for(let x=64;x<288;x+=M.TILE)c.drawImage(images.stone,x,y,M.TILE,M.TILE);const shade=c.createRadialGradient(580,450,100,580,450,780);shade.addColorStop(0,'#203a2610');shade.addColorStop(1,'#03120ed9');c.fillStyle=shade;c.fillRect(0,0,M.WIDTH,M.HEIGHT);}

function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;scale=(width<760||matchMedia('(pointer: coarse)').matches)?Math.max(.95,Math.min(width/420,height/650,1.25)):Math.min(width/820,height/620,1.6);schedule();}
function ellipse(x,y,rx,ry,color,line=false){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);if(line){ctx.strokeStyle=color;ctx.lineWidth=2;ctx.stroke();}else{ctx.fillStyle=color;ctx.fill();}}
